portLiterals.code:
# The query returns one row whose refusal is null when the credit was
# taken and says why when it was not. Returning no "refusal" key closes
# that port, which is what skips the apology message downstream.
row = rows[0]
if row.get("refusal"):
    return {"paid": False, "refusal": row["refusal"]}
return {"paid": True}
